 struct PreparedBlobState {
     payloads: BTreeMap<BlockId, crate::block::PreparedBlockPayload>,
     memory: SnapshotPin,
+}
+
+impl Drop for PreparedBlobState {
+    fn drop(&mut self) {
+        // Preserve payload-before-memory/pin teardown; only measure the map.
+        let _drop = crate::request_profile::TimedWork::new(
+            crate::request_profile::Work::PreparedBlobPayloadDropNanos);
+        crate::request_profile::work(
+            crate::request_profile::Work::PreparedBlobPayloadDropCalls, 1);
+        drop(std::mem::take(&mut self.payloads));
+    }
 }

